"use client"

import { useEffect, useState } from "react"
import type { RealtimePrediction } from "tfl-ts"
import { RailArrivalsBoard } from "@/components/tfl/arrivals/rail-arrivals-board"
import { getStopArrivalsAction } from "@/lib/tfl/live-arrivals-action"
import { useArrivalsBoardUiState } from "@/lib/tfl/use-arrivals-board-ui-state"

const DEFAULT_STOP_ID = "940GZZLUOXC"
const POLL_MS = 20_000

/**
 * Docs/demo helper: polls a stop and passes predictions into {@link RailArrivalsBoard}.
 * Prefer using `RailArrivalsBoard` with `data` directly in applications.
 *
 * @deprecated Prefer RailArrivalsBoard + your own fetch. Legacy registry name only.
 */
export const LiveArrivalsBoard = ({
  stopPointId = DEFAULT_STOP_ID,
  stopName = "Oxford Circus",
}: {
  stopPointId?: string
  stopName?: string
}) => {
  const [data, setData] = useState<RealtimePrediction[]>([])
  const [fetchError, setFetchError] = useState<string | null>(null)
  const [loading, setLoading] = useState(true)
  const [tick, setTick] = useState(0)
  const boardState = useArrivalsBoardUiState(data.length, fetchError, "rail")

  useEffect(() => {
    let cancelled = false
    let timer: ReturnType<typeof setTimeout> | undefined

    const load = async () => {
      try {
        const result = await getStopArrivalsAction(stopPointId)
        if (cancelled) return
        if (!result.ok) {
          setFetchError(result.error)
          setData([])
        } else {
          setFetchError(null)
          setData(result.arrivals)
          setTick((n) => n + 1)
        }
      } catch {
        if (!cancelled) setFetchError("Failed to load arrivals.")
      } finally {
        if (!cancelled) {
          setLoading(false)
          timer = setTimeout(load, POLL_MS)
        }
      }
    }

    void load()
    return () => {
      cancelled = true
      if (timer) clearTimeout(timer)
    }
  }, [stopPointId])

  return (
    <RailArrivalsBoard
      data={data}
      stopName={stopName}
      loading={loading}
      error={boardState.error}
      emptyKind={boardState.emptyKind}
      statusLabel={`Poll #${tick} · every ${POLL_MS / 1000}s`}
    />
  )
}

export { RailArrivalsBoard } from "@/components/tfl/arrivals/rail-arrivals-board"
export { ArrivalsBoardSkeleton } from "@/components/tfl/arrivals/arrivals-board-view"

"use server";

import type { RealtimePrediction } from "tfl-ts";
import {
  getCachedStopArrivals,
  isDemoStopArrivalsId,
} from "@/lib/tfl/cached-stop-arrivals";

export type GetStopArrivalsResult =
  | { ok: true; arrivals: RealtimePrediction[] }
  | { ok: false; error: string };

/** @deprecated Use RealtimePrediction from tfl-ts. */
export type LiveArrival = RealtimePrediction;

/**
 * Docs-demo arrivals fetch for the site key path.
 * Only allowlisted demo stop IDs are served (shared cache).
 * Arbitrary stop IDs are rejected so this cannot be used as an open TfL proxy.
 */
export async function getStopArrivalsAction(
  stopPointId: string,
): Promise<GetStopArrivalsResult> {
  const trimmed = stopPointId.trim();
  if (!trimmed) return { ok: false, error: "No stop selected." };

  if (!isDemoStopArrivalsId(trimmed)) {
    return {
      ok: false,
      error: "This stop is not available on the site key. Add your own TfL API key.",
    };
  }

  try {
    const arrivals = await getCachedStopArrivals(trimmed);
    return { ok: true, arrivals };
  } catch (err) {
    const message =
      err instanceof Error ? err.message : "Failed to fetch arrivals.";
    return { ok: false, error: message };
  }
}

"use client";

import { useEffect, useState, useSyncExternalStore } from "react";
import {
  resolveArrivalsEmptyKind,
  type ArrivalsEmptyKind,
} from "@/lib/tfl/arrivals-empty";

const LOAD_ERROR = "Couldn't load arrivals.";

type ArrivalsBoardUiState = {
  error: string | null;
  emptyKind: ArrivalsEmptyKind;
};

const NOON_SENTINEL_MS = Date.UTC(2020, 0, 1, 12, 0, 0);

// `useSyncExternalStore`'s snapshot must be a *stable* cached value — it is
// re-read on every render, and `Date.now()` returns a new value on every
// call. Reading it directly here would make React see the store as "changed"
// on every render, forcing another render, forever (Maximum update depth
// exceeded). Instead, only mutate the cache inside the subscribe callback,
// which React guarantees runs client-side only, never during SSR/prerender.
let cachedNowMs = NOON_SENTINEL_MS;

const subscribeToMinuteClock = (onStoreChange: () => void) => {
  const sync = () => {
    cachedNowMs = Date.now();
    onStoreChange();
  };
  sync();
  const id = window.setInterval(sync, 60_000);
  return () => window.clearInterval(id);
};

const getClockSnapshot = () => cachedNowMs;
const getServerClockSnapshot = () => NOON_SENTINEL_MS;

/**
 * Client-side empty/error presentation for live demos and polling boards.
 * Distinguishes offline vs fetch failure vs night-ended vs plain empty.
 */
export const useArrivalsBoardUiState = (
  rowCount: number,
  fetchError: string | null,
  domain: "rail" | "bus" = "rail",
): ArrivalsBoardUiState => {
  const [offline, setOffline] = useState(false);
  const nowMs = useSyncExternalStore(
    subscribeToMinuteClock,
    getClockSnapshot,
    getServerClockSnapshot,
  );

  useEffect(() => {
    const sync = () => setOffline(!navigator.onLine);
    queueMicrotask(sync);
    window.addEventListener("online", sync);
    window.addEventListener("offline", sync);
    return () => {
      window.removeEventListener("online", sync);
      window.removeEventListener("offline", sync);
    };
  }, []);

  if (fetchError && !offline) {
    return { error: LOAD_ERROR, emptyKind: "empty" };
  }

  return {
    error: null,
    emptyKind:
      resolveArrivalsEmptyKind({
        rowCount,
        offline: offline && rowCount === 0,
        domain,
        nowMs,
      }) ?? "empty",
  };
};

/**
 * Why an arrivals board has no rows. Callers resolve this from fetch result +
 * clock; the board only paints the copy.
 */
export type ArrivalsEmptyKind = "empty" | "ended" | "offline";

export const ARRIVALS_EMPTY_COPY: Record<ArrivalsEmptyKind, string> = {
  empty: "No arrivals right now.",
  ended: "Service has ended for tonight.",
  offline: "You're offline. Arrivals will update when you're back.",
};

/** Per-line / per-route when predictions are missing but the line is still shown. */
export const ARRIVALS_LINE_EMPTY_COPY = "No information";

const LONDON_TIME_ZONE = "Europe/London";

const londonHourFormatter = new Intl.DateTimeFormat("en-GB", {
  timeZone: LONDON_TIME_ZONE,
  hour: "2-digit",
  hourCycle: "h23",
});

/** Europe/London hour (0–23) for an instant. Pass `nowMs` — never default the clock here. */
export const londonHour = (nowMs: number): number => {
  const hour = londonHourFormatter
    .formatToParts(new Date(nowMs))
    .find((part) => part.type === "hour")?.value;
  return hour ? Number(hour) : 0;
};

/**
 * Rough Underground closed window in London local time. Night buses still run,
 * so prefer `empty` for bus boards unless the caller forces `ended`.
 */
export const isLikelyRailServiceEnded = (nowMs: number): boolean => {
  const hour = londonHour(nowMs);
  return hour >= 1 && hour < 5;
};

type ResolveArrivalsEmptyKindOptions = {
  rowCount: number;
  /** Fetch/render failure — board uses `error` instead. */
  hasError?: boolean;
  offline?: boolean;
  /** Rail uses the overnight `ended` heuristic; bus does not. */
  domain?: "rail" | "bus";
  nowMs: number;
};

/**
 * Pick an empty kind when there are no rows. Returns `null` when the board
 * should show arrivals or an error instead.
 */
export const resolveArrivalsEmptyKind = ({
  rowCount,
  hasError = false,
  offline = false,
  domain = "rail",
  nowMs,
}: ResolveArrivalsEmptyKindOptions): ArrivalsEmptyKind | null => {
  if (hasError || rowCount > 0) return null;
  if (offline) return "offline";
  if (domain !== "bus" && isLikelyRailServiceEnded(nowMs)) return "ended";
  return "empty";
};

import TflClient from "tfl-ts";

export const getTflClient = (): TflClient => {
  const appKey = process.env.TFL_APP_KEY;
  if (!appKey) {
    return new TflClient();
  }
  return new TflClient({ appKey });
};
